#!/usr/bin/env node
async function run() {
  if (process.env.OPENCODE_FLOW_USE_SRC === "1") {
    const mod = await import("../src/cli.ts");
    return mod.main();
  }
  try {
    const mod = await import("../dist/cli.js");
    return mod.main();
  } catch (error) {
    if (error?.code !== "ERR_MODULE_NOT_FOUND") throw error;
    // 本地开发未构建时回退到源码；npm 包内应始终使用 dist。
    const mod = await import("../src/cli.ts");
    return mod.main();
  }
}

run().catch((error) => {
  console.error(error?.message ?? String(error));
  process.exit(1);
});

