function extractQuestionAnswers(result) {
    const out = [];
    const visit = (value, depth = 0) => {
        if (depth > 6 || value == null)
            return;
        if (typeof value === "string") {
            const text = value.trim();
            if (!text)
                return;
            try {
                const parsed = JSON.parse(text);
                if (typeof parsed === "object")
                    return visit(parsed, depth + 1);
            }
            catch {
                // 非 JSON 文本按答案处理。
            }
            out.push(text);
            return;
        }
        if (Array.isArray(value)) {
            for (const item of value)
                visit(item, depth + 1);
            return;
        }
        if (typeof value === "object") {
            for (const key of ["answers", "answer", "selected", "labels", "value", "text"]) {
                if (key in value)
                    visit(value[key], depth + 1);
            }
        }
    };
    if (result?.output !== undefined)
        visit(result.output);
    else if (result?.metadata?.answers !== undefined)
        visit(result.metadata.answers);
    else if (result?.metadata?.answer !== undefined)
        visit(result.metadata.answer);
    else if (result?.content !== undefined)
        visit(result.content);
    if (!out.length && result?.metadata?.answers !== undefined)
        visit(result.metadata.answers);
    return [...new Set(out)];
}
function deferredPath(root) {
    return join(root, ".opencode-flow", "deferred-requests.jsonl");
}
function deferRequest(root, text, reason) {
    try {
        const entry = { at: new Date().toISOString(), reason, text: text.slice(0, 500) };
        const existing = deferredRequests(root, 50);
        // 同一请求只记一次，避免每轮 prompt 都追加；只保留最近 50 条。
        if (existing.some((item) => item.text === entry.text))
            return;
        mkdirSync(join(root, ".opencode-flow"), { recursive: true });
        const lines = [...existing, entry].slice(-50);
        writeFileSync(deferredPath(root), `${lines.map((item) => JSON.stringify(item)).join("\n")}\n`);
    }
    catch {
        // 记录失败不能影响主会话。
    }
}
function deferredRequests(root, limit = 5) {
    try {
        const path = deferredPath(root);
        if (!existsSync(path))
            return [];
        return readFileSync(path, "utf8")
            .split("\n")
            .filter(Boolean)
            .slice(-limit)
            .map((line) => JSON.parse(line));
    }
    catch {
        return [];
    }
}
