        const text = readFileSync(path, "utf8").slice(0, 4000);
        const lines = text
            .split(/\r?\n/)
            .map((line) => line.trim())
            .filter((line) => line && !line.startsWith("```"))
            .slice(0, 3)
            .join(" / ");
        return lines.length > max ? `${lines.slice(0, max)}…` : lines;
    }
    catch {
        return "";
    }
}
/** 计划卡/验收卡不能只有“通过/驳回”；这里收集人能直接判断的摘要与证据路径。 */
function decisionDigest(root, workItemId, kind) {
    if (!workItemId)
        return { summary: "", evidence: [], paths: [] };
    const base = join(root, "docs", "flow", workItemId);
    const paths = [];
    const summary = [];
    if (kind === "plan") {
        const candidates = ["intent.md", "options.md", "spec.md", "plan.md", "tasks.md"];
        for (const name of candidates) {
            const path = join(base, name);
            if (!existsSync(path))
                continue;
            paths.push(`docs/flow/${workItemId}/${name}`);
            const text = digestMarkdown(path);
            if (text)
                summary.push(`${name}: ${text}`);
        }
        const architecture = join(base, "architecture");
        if (existsSync(architecture)) {
            try {
                for (const entry of readdirSync(architecture).filter((name) => name.endsWith(".md")).slice(0, 3)) {
                    const path = join(architecture, entry);
                    paths.push(`docs/flow/${workItemId}/architecture/${entry}`);
                    const text = digestMarkdown(path);
                    if (text)
                        summary.push(`architecture/${entry}: ${text}`);
                }
            }
            catch {
                // 目录不可读时不阻塞卡片。
            }
        }
        return { summary: summary.join("\n"), evidence: [], paths };
    }
    const evidence = new Set();
    const tasks = (() => {
        try {
            const engine = new TrustEngine(root);
            try {
                return engine.tasks(workItemId);
            }
            finally {
                engine.dispose();
            }
        }
        catch {
            return [];
        }
    })();
    for (const task of tasks) {
        for (const item of task.evidence ?? []) {
            const path = String(item).split("#")[0];
            if (path)
                evidence.add(path);
        }
    }
    for (const path of evidence) {
        const full = join(root, path);
        paths.push(path);
        if (existsSync(full)) {
            const text = digestMarkdown(full, 160);
            if (text)
                summary.push(`${path}: ${text}`);
        }
    }
    return { summary: summary.join("\n"), evidence: [...evidence], paths };
}
/** 用户唯一需要的状态视图：一屏回答“现在到哪了、要我做什么”。 */
function flowDashboard(engine, root) {
    const items = engine.status();
    const active = items.filter((item) => item.status === "active" || item.status === "awaiting_outcome");
    if (!active.length)
        return "没有进行中的工作。直接说需求或 Bug。";
    const current = active.find((item) => item.tasks.some((task) => task.status === "claimed")) ?? active[0];
    const tasks = Array.isArray(current.tasks) ? current.tasks : [];
    const ready = tasks.filter((task) => task.status === "ready");
    const humanReady = ready.filter((task) => task.human);
    const blocked = tasks.filter((task) => task.status === "blocked");
    const claimed = tasks.find((task) => task.status === "claimed");
    let daemon = { alive: false };
    try {
        daemon = trustDaemonStatus(root);
    }
    catch {
        // daemon 状态不可用时不影响主视图。
    }
    const deferred = deferredRequests(root);
    const pending = current.status === "awaiting_outcome" ? ["验收"] : humanReady.map(taskLabel);
    const lines = [
        `当前：${current.title}  [${PLAYBOOK_LABELS[current.playbook] ?? current.playbook} / ${RISK_LABELS[current.risk] ?? current.risk}]`,
        `进度：${current.counts?.done ?? 0}/${current.counts?.total ?? tasks.length} 任务完成${claimed ? "，执行中" : ""}`,
        `待你决定：${pending.length ? pending.join("、") : "无"}`,
        `阻塞：${blocked.length ? blocked.map(taskLabel).join("、") : "无"}`,
        `后台：${daemon.alive ? "运行中" : "未运行"}`,
    ];
    if (deferred.length)
        lines.push(`排队请求：${deferred.length} 条`);
    if (current.status === "awaiting_outcome") {
        lines.push("下一步：需要你验收");
    }
    else if (humanReady.length) {
        lines.push(`下一步：等你处理「${taskLabel(humanReady[0])}」`);
    }
    else if (claimed) {
        lines.push(`下一步：正在执行「${taskLabel(claimed)}」`);
    }
    else if (ready.length) {
        lines.push(`下一步：即将开始「${taskLabel(ready[0])}」`);
    }
    else if (blocked.length) {
        lines.push(`下一步：先处理阻塞「${taskLabel(blocked[0])}」，可以说“为什么卡住”`);
    }
    else {
        lines.push("下一步：等待执行中的任务完成");
    }
    if (active.length > 1)
        lines.push(`另有 ${active.length - 1} 个工作项进行中`);
    return lines.join("\n");
}
function xml(value) {
    return String(value ?? "").replace(/[<>&"']/g, (char) => char === "<" ? "&lt;" : char === ">" ? "&gt;" : char === "&" ? "&amp;" : char === '"' ? "&quot;" : "&#39;");
}
// 低风险/计划型 playbook 在立项后自动执行；feature/high-assurance/refactor 在计划批准后启动。
function maybeStartDaemon(root) {
    if (process.env.OPENCODE_FLOW_NO_DAEMON === "1" || process.env.OPENCODE_FLOW_HEADLESS === "1") {
        return { started: false, skipped: true };
    }
    try {
        return startTrustDaemon(root);
    }
    catch (error) {
        return { started: false, reason: error?.message ?? String(error) };
    }
}
